using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed metadata retrieval: GetTypeInfo<T>() extension method
//    returns JsonTypeInfo<T> directly — no cast needed.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");
Console.WriteLine($"  Kind: {personInfo.Kind}");

// 2) Probe without throwing: TryGetTypeInfo returns false if unavailable.
//    Here we use an options instance with NO resolver, so nothing is resolvable.
var empty = new JsonSerializerOptions { TypeInfoResolver = null };

bool found = empty.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info);
Console.WriteLine();
Console.WriteLine($"TryGetTypeInfo on empty options: found={found}, info={info?.Type.Name ?? "(null)"}");

// Also show a successful probe:
bool found2 = options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info2);
Console.WriteLine($"TryGetTypeInfo on configured options: found={found2}, info={info2?.Type.Name ?? "(null)"}");

// You can safely cast the probed result to the generic form when found:
if (found2 && info2 is JsonTypeInfo<Person> typed)
{
    Console.WriteLine($"  Successfully cast to JsonTypeInfo<Person>, Kind={typed.Kind}");
}

public record Person(string Name, int Age);

